using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using Axpense.Api.Data;
namespace Axpense.Api.Controllers;
[ApiController][Route("api/dashboard")]
public class DashboardController(AxpenseDbContext db):ControllerBase
{
 [HttpGet] public async Task<IActionResult> Get(Guid organizationId){var now=DateTime.UtcNow;var monthStart=new DateTime(now.Year,now.Month,1);var next=monthStart.AddMonths(1);var vehicles=await db.Vehicles.CountAsync(v=>v.OrganizationId==organizationId);var active=await db.Vehicles.CountAsync(v=>v.OrganizationId==organizationId&&v.Status=="Active");var maintenanceDue=await db.MaintenanceRecords.CountAsync(x=>x.OrganizationId==organizationId&&x.Status!="Completed"&&x.DueDate>=now.Date&&x.DueDate<=now.Date.AddDays(30));var open=await db.MaintenanceRecords.CountAsync(x=>x.OrganizationId==organizationId&&x.Status!="Completed");var expenses=await db.Expenses.Where(x=>x.OrganizationId==organizationId&&x.ExpenseDate>=monthStart&&x.ExpenseDate<next).SumAsync(x=>(decimal?)x.Amount)??0;var fuel=await db.FuelTransactions.Where(x=>x.OrganizationId==organizationId&&x.TransactionDate>=monthStart&&x.TransactionDate<next).SumAsync(x=>(decimal?)x.TotalAmount)??0;var maintenance=await db.MaintenanceRecords.Where(x=>x.OrganizationId==organizationId&&x.CompletedAtUtc>=monthStart&&x.CompletedAtUtc<next).SumAsync(x=>(decimal?)x.ActualCost)??0;return Ok(new{totalVehicles=vehicles,activeVehicles=active,maintenanceDueWithin30Days=maintenanceDue,openWorkOrders=open,monthlyExpenses=expenses,monthlyFuel=fuel,monthlyMaintenance=maintenance,monthlyTotalCost=expenses+fuel+maintenance});}
}
